const ideas = $input.all().filter(i => i.json.Sujet && i.json.Status).map(i => i.json);
const calendar = $input.all().filter(i => i.json.Semaine).map(i => i.json);

const newIdeas = ideas.filter(i => i.Status === 'nouveau' || i.Status === 'validé');
const existingSubjects = calendar.map(c => c.Sujet).filter(Boolean);

return [{
  json: {
    available_ideas: newIdeas.slice(0, 20),
    existing_subjects: existingSubjects,
    week_start: new Date(Date.now() + 86400000).toISOString().split('T')[0]
  }
}];

const response = $input.first().json;

// Native Gemini node returns { content: { parts: [{ text: '...' }] }, finishReason, index }
// Old HTTP API returned { candidates: [{ content: { parts: [{ text: '...' }] } }] }

let parsed;
try {
  let text = '';

  if (response.content?.parts) {
    // Native node format
    text = response.content.parts.map(p => p.text || '').join('');
  } else if (response.candidates?.[0]?.content?.parts) {
    // HTTP API format
    text = response.candidates[0].content.parts.map(p => p.text || '').join('');
  } else if (typeof response === 'string') {
    text = response;
  } else if (response.calendar) {
    // Already parsed JSON
    parsed = response;
  } else {
    text = JSON.stringify(response);
  }

  if (!parsed && text) {
    // Strip markdown code fences if present
    text = text.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
    parsed = JSON.parse(text);
  }
} catch (e) {
  throw new Error('Erreur parsing calendrier Gemini: ' + e.message + ' — texte reçu: ' + JSON.stringify(response).substring(0, 300));
}

const rows = [];
const now = new Date();
const weekNum = Math.ceil((now.getTime() - new Date(now.getFullYear(), 0, 1).getTime()) / (7 * 86400000));

for (const day of (parsed.calendar || [])) {
  for (const post of (day.posts || [])) {
    rows.push({
      Semaine: 'S' + weekNum,
      Jour: day.day || '',
      Date: day.date || '',
      Heure_GMT: post.time || '',
      Reseau: post.network || '',
      Format: post.format || '',
      Rubrique: post.rubrique || '',
      Sujet: post.subject || '',
      Contenu: post.hook || '',
      Media_URL: '',
      Hashtags: (post.hashtags || []).join(' '),
      Status_Contenu: 'a_produire',
      Status_Media: post.media_needed && post.media_needed !== 'none' ? 'a_produire' : 'n/a',
      Status_Publication: 'planifie',
      URL_Post: '',
      Media_Prompt: post.media_prompt || ''
    });
  }
}

if (rows.length === 0) {
  throw new Error('Aucune ligne générée. Réponse Gemini parsed: ' + JSON.stringify(parsed).substring(0, 500));
}

return rows.map(r => ({ json: r }));
